// Mobile-app continuity: 604-page reader position and page completion.
function syncReaderPosition(){state.readerPage=Math.max(1,Math.min(TOTAL,state.readerPage||Math.min(TOTAL,state.completed+1)));if($('#readerPageLabel'))$('#readerPageLabel').textContent=(state.lang==='ar'?'صفحة ':'Page ')+state.readerPage+(state.lang==='ar'?' من ':' of ')+TOTAL;save()}
$('#prevReaderPage').onclick=()=>{state.readerPage=Math.max(1,(state.readerPage||1)-1);syncReaderPosition()};$('#nextReaderPage').onclick=()=>{state.readerPage=Math.min(TOTAL,(state.readerPage||1)+1);syncReaderPosition()};
const oldOpenPage=openPage;openPage=function(id){oldOpenPage(id);if(id==='quran')syncReaderPosition()};syncReaderPosition();
// Full 604-page Madinah Mushaf reader — original app page images, no text transformations.
let quranPages=[],quranReady=false,mushafScale=1;
const pageSrc=p=>new URL('./assets/mushaf_pages/p'+String(p).padStart(3,'0')+'.jpg',location.href).href;
async function loadQuran(){if(quranReady)return true;try{const r=await fetch('./quran-pages.json',{cache:'force-cache'});if(!r.ok)throw 0;quranPages=await r.json();if(!Array.isArray(quranPages)||quranPages.length!==604)throw 0;quranReady=true;renderQuranPage();return true}catch(e){$('#quranLoading').hidden=false;$('#quranLoading').textContent='تعذر التحقق من فهرس صفحات المصحف. لن نعرض صفحات غير متحقق من بنيتها.';return false}}
function renderQuranPage(){if(!quranReady)return;syncReaderPosition();const p=state.readerPage||1,img=$('#mushafPageImage');if($('#quranPageSelect'))$('#quranPageSelect').value=p;$('#quranLoading').hidden=false;$('#quranLoading').innerHTML='<span class="loader-spinner" aria-hidden="true"></span><span>جاري تحميل الصفحة '+p+'…</span>';const src=pageSrc(p);img.onload=()=>{if(img.src!==src)return;$('#quranLoading').hidden=true;img.hidden=false;};img.onerror=()=>{if(img.src!==src)return;img.hidden=true;$('#quranLoading').hidden=false;$('#quranLoading').innerHTML='تعذر تحميل صفحة المصحف رقم '+p+'.<br><small>المسار: assets/mushaf_pages/p'+String(p).padStart(3,'0')+'.jpg</small>'};img.src=src;const start=quranPages[p-1];if(start&&$('#surahSelect'))$('#surahSelect').selectedIndex=start.sura-1;resetZoom()}
function findPageForAyah(s,a){let found=1;for(let i=0;i<quranPages.length;i++){const p=quranPages[i];if(p.sura<s||(p.sura===s&&p.aya<=a))found=i+1;else break}return found}
function renderBookmarks(){const host=$('#bookmarks .empty-state');if(!host)return;const x=JSON.parse(localStorage.getItem('khatm-page-bookmarks')||'[]');if(!x.length){host.innerHTML='<b>♡</b><h2>لا توجد علامات بعد</h2><p>يمكنك حفظ صفحة القراءة الحالية من زر العلامات.</p><button class="primary goto" data-target="quran">افتح القرآن</button>';host.querySelector('.goto').onclick=()=>openPage('quran');return}host.innerHTML='<div class="bookmark-list">'+x.map((p,i)=>'<button data-pb="'+i+'"><b>صفحة '+p+'</b><span>العودة إلى موضع القراءة</span></button>').join('')+'</div>';$$('[data-pb]').forEach(b=>b.onclick=()=>{state.readerPage=x[+b.dataset.pb];save();openPage('quran')})}
$('#readerBookmarks').onclick=()=>{let x=JSON.parse(localStorage.getItem('khatm-page-bookmarks')||'[]'),p=state.readerPage||1;if(!x.includes(p))x.push(p);localStorage.setItem('khatm-page-bookmarks',JSON.stringify(x));renderBookmarks();showInfo('تم الحفظ','تم حفظ صفحة '+p+' في العلامات.')};
$('#surahSelect').onchange=()=>{const s=$('#surahSelect').selectedIndex+1;state.readerPage=findPageForAyah(s,1);save();renderQuranPage()};
$('#prevReaderPage').onclick=()=>{state.readerPage=Math.max(1,(state.readerPage||1)-1);save();renderQuranPage()};
$('#nextReaderPage').onclick=()=>{state.readerPage=Math.min(TOTAL,(state.readerPage||1)+1);save();renderQuranPage()};
function applyZoom(){const img=$('#mushafPageImage');img.style.width=(mushafScale*100)+'%';$('#zoomLabel').textContent=Math.round(mushafScale*100)+'%'}
function resetZoom(){mushafScale=1;applyZoom();const v=$('#mushafViewport');v.scrollTop=0;v.scrollLeft=0}
$('#zoomIn').onclick=()=>{mushafScale=Math.min(5,mushafScale+.25);applyZoom()};$('#zoomOut').onclick=()=>{mushafScale=Math.max(1,mushafScale-.25);applyZoom()};$('#zoomReset').onclick=resetZoom;
const vp=$('#mushafViewport');let pinchStart=0,pinchScale=1;const dist=t=>Math.hypot(t[0].clientX-t[1].clientX,t[0].clientY-t[1].clientY);vp.addEventListener('touchstart',e=>{if(e.touches.length===2){pinchStart=dist(e.touches);pinchScale=mushafScale}},{passive:true});vp.addEventListener('touchmove',e=>{if(e.touches.length===2&&pinchStart){e.preventDefault();mushafScale=Math.max(1,Math.min(5,pinchScale*dist(e.touches)/pinchStart));applyZoom()}},{passive:false});
const baseOpenPage=openPage;openPage=function(id){baseOpenPage(id);if(id==='quran')loadQuran();if(id==='bookmarks')renderBookmarks()};
$('#quranSearchBtn').onclick=()=>{const q=$('#quranSearch').value.trim();if(!q)return;const n=Number(q);if(Number.isInteger(n)&&n>=1&&n<=604){state.readerPage=n;save();openPage('quran');return}renderIndex('surahs')};
renderBookmarks();
// v17 manual city fallback: geocode only on explicit user action, then reuse the same prayer/qibla math.
const manualLocationBtn=$('#manualLocationBtn');if(manualLocationBtn)manualLocationBtn.onclick=async()=>{const city=$('#manualCity').value.trim(),country=$('#manualCountry').value.trim(),box=$('#prayerStatus');if(!city||!country){box.className='notice';box.textContent='أدخل المدينة والدولة.';return}try{box.className='notice';box.textContent='جاري تحديد المدينة…';const r=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q='+encodeURIComponent(city+', '+country),{headers:{'Accept-Language':'ar,en'}});if(!r.ok)throw 0;const a=await r.json();if(!a.length)throw 0;const lat=+a[0].lat,lon=+a[0].lon,deg=qibla(lat,lon);$('#qiblaDegrees').textContent=Math.round(deg)+'°';$('#needle').style.transform='rotate('+deg+'deg)';await loadPrayerTimes(lat,lon)}catch(e){box.className='notice';box.textContent='تعذر العثور على المدينة. تحقق من الاسم والدولة وحاول مجددًا.'}};


// v33 — Khatm Wird reader is completely independent from the free Quran reader.
let wirdCtx=null,wirdScale=1;
function getDailyWird(){
 const elapsed=Math.max(1,Math.floor((new Date()-new Date(state.start+'T00:00:00'))/864e5)+1);
 const daily=Math.ceil((TOTAL-state.completed)/Math.max(1,state.days-elapsed+1));
 const start=Math.min(TOTAL,state.completed+1),end=Math.min(TOTAL,state.completed+daily);
 const parts=state.mode==='prayers'?5:state.mode==='three'?3:1;
 const names=state.mode==='prayers'?prayerNames[state.lang]:(state.mode==='three'?(state.lang==='ar'?['صباحًا','ظهرًا','مساءً']:state.lang==='ur'?['صبح','دوپہر','شام']:['Morning','Noon','Evening']):(state.lang==='ar'?['جلسة اليوم']:state.lang==='ur'?['آج کی نشست']:['Daily session']));
 return {start,end,daily,parts,names,sessions:Array.from({length:parts},(_,i)=>({i,name:names[i],start:start+Math.floor(daily/parts*i),end:i===parts-1?end:Math.min(end,start+Math.floor(daily/parts*(i+1))-1)})).filter(x=>x.start<=x.end)};
}
function openWird(index){
 const d=getDailyWird(); if(state.completed>=TOTAL){showInfo('الختمة مكتملة','تم إتمام صفحات الختمة الحالية.');return}
 let i=Number.isInteger(index)?index:d.sessions.findIndex(x=>!state.done.includes(x.i)); if(i<0)i=0;
 const s=d.sessions.find(x=>x.i===i)||d.sessions[0]; if(!s)return;
 wirdCtx={index:s.i,start:s.start,end:s.end,page:s.start,name:s.name};wirdScale=1;openPage('wirdReader');renderWird();
}
function renderWird(){
 if(!wirdCtx)return;const img=$('#wirdPageImage'),p=wirdCtx.page,src=pageSrc(p);
 $('#wirdTitle').textContent='ورد '+wirdCtx.name;$('#wirdSessionLabel').textContent='الصفحات '+wirdCtx.start+'–'+wirdCtx.end;
 $('#wirdRangeLabel').textContent='صفحة '+p+' من '+wirdCtx.end;
 const total=wirdCtx.end-wirdCtx.start+1,done=p-wirdCtx.start;$('#wirdProgressBar').style.width=Math.round(done/total*100)+'%';
 $('#wirdPrev').disabled=p<=wirdCtx.start;$('#wirdNext').disabled=p>=wirdCtx.end;$('#finishWird').disabled=p<wirdCtx.end;
 $('#wirdLoading').hidden=false;img.hidden=true;img.onload=()=>{$('#wirdLoading').hidden=true;img.hidden=false};img.onerror=()=>{$('#wirdLoading').hidden=false;$('#wirdLoading').textContent='تعذر تحميل صفحة الورد رقم '+p};img.src=src;applyWirdZoom();
}
function applyWirdZoom(){const img=$('#wirdPageImage');if(!img)return;img.style.width=(wirdScale*100)+'%';$('#wirdZoomLabel').textContent=Math.round(wirdScale*100)+'%'}
$('#wirdPrev').onclick=()=>{if(wirdCtx&&wirdCtx.page>wirdCtx.start){wirdCtx.page--;renderWird()}};
$('#wirdNext').onclick=()=>{if(wirdCtx&&wirdCtx.page<wirdCtx.end){wirdCtx.page++;renderWird()}};
$('#wirdZoomIn').onclick=()=>{wirdScale=Math.min(5,wirdScale+.25);applyWirdZoom()};$('#wirdZoomOut').onclick=()=>{wirdScale=Math.max(1,wirdScale-.25);applyWirdZoom()};$('#wirdZoomReset').onclick=()=>{wirdScale=1;applyWirdZoom();$('#wirdViewport').scrollTop=0;$('#wirdViewport').scrollLeft=0};
$('#closeWird').onclick=()=>openPage('home');
$('#finishWird').onclick=()=>{if(!wirdCtx||wirdCtx.page<wirdCtx.end)return;if(!state.done.includes(wirdCtx.index))state.done.push(wirdCtx.index);const d=getDailyWird();if(state.done.length>=d.parts){state.completed=Math.min(TOTAL,d.end);state.done=[]}save();render();updateStatsPage();openPage('home');};

// v37 — dedicated Qibla + city prayer times, no maps.
let qiblaBearing=null,orientationBound=false;
function setQibla(lat,lon,label){qiblaBearing=qibla(lat,lon);$('#qiblaAngle').textContent=qiblaBearing.toFixed(1)+'°';$('#qiblaArrow').style.transform='rotate('+qiblaBearing+'deg)';$('#qiblaPlace').textContent=label||'الموقع المحدد';$('#qiblaStatus').textContent='تم حساب الاتجاه بطريقة الدائرة العظمى نحو الكعبة.'}
function locateQibla(){if(!navigator.geolocation){$('#qiblaStatus').textContent='تحديد الموقع غير متاح على هذا الجهاز.';return}$('#qiblaStatus').textContent='جاري تحديد موقعك…';navigator.geolocation.getCurrentPosition(p=>setQibla(p.coords.latitude,p.coords.longitude,'موقعك الحالي'),()=>$('#qiblaStatus').textContent='لم يتم منح إذن الموقع. استخدم المدينة والدولة بدلًا منه.',{enableHighAccuracy:true,timeout:10000})}
async function geocodeQiblaCity(){const city=$('#qiblaCity').value.trim(),country=$('#qiblaCountry').value.trim();if(!city||!country){$('#qiblaStatus').textContent='أدخل المدينة والدولة.';return}$('#qiblaStatus').textContent='جاري تحديد المدينة…';try{const r=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q='+encodeURIComponent(city+', '+country),{headers:{'Accept-Language':'ar,en'}}),j=await r.json();if(!j.length)throw 0;setQibla(+j[0].lat,+j[0].lon,city+'، '+country)}catch(e){$('#qiblaStatus').textContent='تعذر العثور على المدينة. تحقق من الاسم وحاول مجددًا.'}}
function orientationHandler(e){let h=typeof e.webkitCompassHeading==='number'?e.webkitCompassHeading:(typeof e.alpha==='number'?(360-e.alpha)%360:null);if(h==null)return;$('#deviceHeading').textContent=Math.round(h)+'°';if(qiblaBearing==null){$('#facingQibla').textContent='حدّد موقعك أولًا';return}let d=((qiblaBearing-h+540)%360)-180;$('#qiblaArrow').style.transform='rotate('+d+'deg)';$('#facingQibla').textContent=Math.abs(d)<=7?'أنت باتجاه القبلة ✓':(d>0?'لف الهاتف يمينًا '+Math.round(Math.abs(d))+'°':'لف الهاتف يسارًا '+Math.round(Math.abs(d))+'°')}
async function enableCompass(){try{if(typeof DeviceOrientationEvent!=='undefined'&&typeof DeviceOrientationEvent.requestPermission==='function'){const p=await DeviceOrientationEvent.requestPermission();if(p!=='granted')throw 0}if(!orientationBound){window.addEventListener('deviceorientationabsolute',orientationHandler,true);window.addEventListener('deviceorientation',orientationHandler,true);orientationBound=true}$('#qiblaStatus').textContent='البوصلة الحية مفعلة. ابتعد عن المعادن وعاير الهاتف بحركة ∞ إذا لزم.'}catch(e){$('#qiblaStatus').textContent='تعذر تفعيل حساس الاتجاه. ما زالت درجة القبلة من الشمال الحقيقي متاحة.'}}
if($('#qiblaLocateBtn'))$('#qiblaLocateBtn').onclick=locateQibla;if($('#qiblaCityBtn'))$('#qiblaCityBtn').onclick=geocodeQiblaCity;if($('#qiblaCompassBtn'))$('#qiblaCompassBtn').onclick=enableCompass;

const prayerNamesFull=[['Fajr','الفجر'],['Sunrise','الشروق'],['Dhuhr','الظهر'],['Asr','العصر'],['Maghrib','المغرب'],['Isha','العشاء']];
async function loadCityPrayers(){const city=$('#ptCity').value.trim(),country=$('#ptCountry').value.trim(),method=$('#ptMethod').value;if(!city||!country){$('#ptLocationTitle').textContent='أدخل المدينة والدولة أولًا';return}$('#ptLocationTitle').textContent='جاري تحميل المواقيت…';$('#ptGrid').innerHTML='';try{const u='https://api.aladhan.com/v1/timingsByCity?city='+encodeURIComponent(city)+'&country='+encodeURIComponent(country)+'&method='+encodeURIComponent(method);const r=await fetch(u),j=await r.json();if(!r.ok||!j.data)throw 0;const t=j.data.timings;$('#ptLocationTitle').textContent=city+'، '+country;$('#ptGrid').innerHTML=prayerNamesFull.map(x=>'<div><span>'+x[1]+'</span><b>'+t[x[0]]+'</b></div>').join('');const now=new Date(),mins=now.getHours()*60+now.getMinutes(),salat=prayerNamesFull.filter(x=>x[0]!=='Sunrise');let next=salat.find(x=>{const z=t[x[0]].match(/\d{1,2}:\d{2}/);if(!z)return false;const [hh,mm]=z[0].split(':').map(Number);return hh*60+mm>mins});let tomorrow=false;if(!next){next=salat[0];tomorrow=true}$('#ptNext').innerHTML='<span>الصلاة القادمة</span><b>'+next[1]+'</b><small>'+t[next[0]]+(tomorrow?' • غدًا':'')+'</small>';const g=j.data.date?.gregorian?.date||'',h=j.data.date?.hijri;$('#ptDate').textContent=(h?h.day+' '+h.month.ar+' '+h.year+' هـ':'')+(g?' • '+g:'');localStorage.setItem('khatm-prayer-city',JSON.stringify({city,country,method}))}catch(e){$('#ptLocationTitle').textContent='تعذر تحميل المواقيت. تحقق من المدينة والدولة وحاول مرة أخرى.'}}
if($('#ptLoadBtn'))$('#ptLoadBtn').onclick=loadCityPrayers;



// v39 — prayer times can use explicit current location, with manual city kept as fallback.
async function loadPrayerCoords(lat,lon,label){const method=$('#ptMethod').value;$('#ptLocationTitle').textContent='جاري تحميل المواقيت…';$('#ptGrid').innerHTML='';try{const u='https://api.aladhan.com/v1/timings/'+Math.floor(Date.now()/1000)+'?latitude='+encodeURIComponent(lat)+'&longitude='+encodeURIComponent(lon)+'&method='+encodeURIComponent(method);const r=await fetch(u),j=await r.json();if(!r.ok||!j.data)throw 0;const t=j.data.timings;$('#ptLocationTitle').textContent=label||'موقعك الحالي';$('#ptGrid').innerHTML=prayerNamesFull.map(x=>'<div><span>'+x[1]+'</span><b>'+t[x[0]]+'</b></div>').join('');const now=new Date(),mins=now.getHours()*60+now.getMinutes(),salat=prayerNamesFull.filter(x=>x[0]!=='Sunrise');let next=salat.find(x=>{const z=t[x[0]].match(/\d{1,2}:\d{2}/);if(!z)return false;const [hh,mm]=z[0].split(':').map(Number);return hh*60+mm>mins}),tomorrow=false;if(!next){next=salat[0];tomorrow=true}$('#ptNext').innerHTML='<span>الصلاة القادمة</span><b>'+next[1]+'</b><small>'+t[next[0]]+(tomorrow?' • غدًا':'')+'</small>';const g=j.data.date?.gregorian?.date||'',hh=j.data.date?.hijri;$('#ptDate').textContent=(hh?hh.day+' '+hh.month.ar+' '+hh.year+' هـ':'')+(g?' • '+g:'')}catch(e){$('#ptLocationTitle').textContent='تعذر تحميل المواقيت من موقعك الآن.'}}
function locatePrayerTimes(){if(!navigator.geolocation){$('#ptLocationTitle').textContent='تحديد الموقع غير متاح على هذا الجهاز. استخدم المدينة والدولة.';return}$('#ptLocationTitle').textContent='جاري تحديد موقعك…';navigator.geolocation.getCurrentPosition(p=>loadPrayerCoords(p.coords.latitude,p.coords.longitude,'موقعك الحالي'),()=>$('#ptLocationTitle').textContent='لم يتم منح إذن الموقع. يمكنك إدخال المدينة والدولة يدويًا.',{enableHighAccuracy:true,timeout:10000})}
if($('#ptLocateBtn'))$('#ptLocateBtn').onclick=locatePrayerTimes;


