// v44 — Hijri/Gregorian calendar and date conversion.
const hijriMonthsAr=['محرم','صفر','ربيع الأول','ربيع الآخر','جمادى الأولى','جمادى الآخرة','رجب','شعبان','رمضان','شوال','ذو القعدة','ذو الحجة'];
function apiDate(d){const [y,m,day]=d.split('-');return day+'-'+m+'-'+y}
function fillCalendarControls(){if(!$('#hijriDay'))return;$('#hijriDay').innerHTML=Array.from({length:30},(_,i)=>'<option value="'+(i+1)+'">'+(i+1)+'</option>').join('');$('#hijriMonth').innerHTML=hijriMonthsAr.map((x,i)=>'<option value="'+(i+1)+'">'+x+'</option>').join('');$('#hijriYear').innerHTML=Array.from({length:201},(_,i)=>'<option value="'+(1350+i)+'">'+(1350+i)+'</option>').join('');const gm=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];$('#gregDay').innerHTML=Array.from({length:31},(_,i)=>'<option value="'+(i+1)+'">'+(i+1)+'</option>').join('');$('#gregMonth').innerHTML=gm.map((x,i)=>'<option value="'+(i+1)+'">'+x+'</option>').join('');const cy=new Date().getFullYear();$('#gregYear').innerHTML=Array.from({length:201},(_,i)=>{const y=cy-100+i;return '<option value="'+y+'">'+y+'</option>'}).join('');const today=new Date();$('#gregDay').value=today.getDate();$('#gregMonth').value=today.getMonth()+1;$('#gregYear').value=today.getFullYear();syncGregorianDate();['gregDay','gregMonth','gregYear'].forEach(id=>$('#'+id).onchange=syncGregorianDate)}
function syncGregorianDate(){if(!$('#gregDateInput'))return;const y=+$('#gregYear').value,m=+$('#gregMonth').value,d=+$('#gregDay').value,max=new Date(y,m,0).getDate();if(d>max){$('#gregDay').value=max}$('#gregDateInput').value=String(y).padStart(4,'0')+'-'+String(m).padStart(2,'0')+'-'+String(+$('#gregDay').value).padStart(2,'0')}
function showCalResult(main,sub){$('#calendarResult').innerHTML='<span>نتيجة التحويل</span><b>'+main+'</b><small>'+sub+'</small>'}
async function convertG2H(silent=false){const v=$('#gregDateInput').value;if(!v)return;try{const r=await fetch('https://api.aladhan.com/v1/gToH/'+apiDate(v)),j=await r.json();if(!j.data)throw 0;const h=j.data.hijri,g=j.data.gregorian;const main=h.day+' '+(h.month?.ar||h.month?.en||'')+' '+h.year+' هـ';const sub=g.day+' '+(g.month?.en||'')+' '+g.year;if(silent){$('#calTodayHijri').textContent=main;$('#calTodayGregorian').textContent=sub}else showCalResult(main,sub)}catch(e){if(!silent)showCalResult('تعذر التحويل','حاول مرة أخرى')}}
async function convertH2G(){const d=$('#hijriDay').value,m=$('#hijriMonth').value,y=$('#hijriYear').value;try{const r=await fetch('https://api.aladhan.com/v1/hToG/'+d+'-'+m+'-'+y),j=await r.json();if(!j.data)throw 0;const g=j.data.gregorian,h=j.data.hijri;showCalResult(g.day+' '+(g.month?.en||'')+' '+g.year,h.day+' '+(h.month?.ar||h.month?.en||'')+' '+h.year+' هـ')}catch(e){showCalResult('تعذر التحويل','تحقق من التاريخ وحاول مجددًا')}}
fillCalendarControls();if($('#g2hBtn'))$('#g2hBtn').onclick=()=>convertG2H(false);if($('#h2gBtn'))$('#h2gBtn').onclick=convertH2G;Array.from(document.querySelectorAll('[data-cal-tab]')).forEach(b=>b.onclick=()=>{Array.from(document.querySelectorAll('[data-cal-tab]')).forEach(x=>x.classList.toggle('selected',x===b));const g=b.dataset.calTab==='g2h';$('#g2hPanel').hidden=!g;$('#h2gPanel').hidden=g});convertG2H(true);


// v45 — shared location context + global animated install control.
const SHARED_LOCATION_KEY='khatm-shared-location';
