function getSharedLocation(){try{const x=JSON.parse(localStorage.getItem(SHARED_LOCATION_KEY)||'null');return x&&Number.isFinite(x.lat)&&Number.isFinite(x.lon)?x:null}catch(e){return null}}
function useSharedLocationAcrossPages(lat,lon,label='موقعك الحالي'){saveSharedLocation(lat,lon,label);try{setQibla(lat,lon,label)}catch(e){}try{loadPrayerCoords(lat,lon,label)}catch(e){}}
