// v51 — audit hardening: install action, timezone-safe prayer clock, cache fallback, shared manual location.
function minutesInZone(timeZone){try{const parts=new Intl.DateTimeFormat('en-GB',{timeZone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date());const h=Number(parts.find(x=>x.type==='hour')?.value),m=Number(parts.find(x=>x.type==='minute')?.value);return Number.isFinite(h)&&Number.isFinite(m)?h*60+m:null}catch(e){return null}}
function renderPrayerDashboardV51(t,label,dateData,timeZone){const localMins=minutesInZone(timeZone),now=new Date(),mins=localMins??(now.getHours()*60+now.getMinutes()),salat=prayerNamesFull.filter(x=>x[0]!=='Sunrise');let next=salat.find(x=>{const z=cleanPrayerTime(t[x[0]]);if(z==='—')return false;const [hh,mm]=z.split(':').map(Number);return hh*60+mm>mins}),tomorrow=false;if(!next){next=salat[0];tomorrow=true}const nextKey=next[0],nextTime=cleanPrayerTime(t[nextKey]);$('#ptLocationTitle').textContent=label||'مواقيت اليوم';$('#ptGrid').innerHTML=prayerNamesFull.map(x=>'<div class="prayer-row '+(x[0]===nextKey?'is-next':'')+'"><span class="prayer-row-icon">'+prayerIcon(x[0])+'</span><b>'+x[1]+'</b>'+(x[0]===nextKey?'<em>التالية</em>':'')+'<strong>'+cleanPrayerTime(t[x[0]])+'</strong></div>').join('');$('#ptNext').innerHTML='<span>الصلاة القادمة: '+next[1]+'</span><b id="ptCountdown">--:--:--</b><small>'+nextTime+(tomorrow?' • غدًا':'')+'</small>';const g=dateData?.gregorian?.date||'',hh=dateData?.hijri;$('#ptDate').textContent=(hh?hh.day+' '+hh.month.ar+' '+hh.year+' هـ':'')+(g?' • '+g:'');lastPrayerSchedule={t,label,dateData,timeZone};try{localStorage.setItem('khatm-last-prayers',JSON.stringify(lastPrayerSchedule))}catch(e){};startPrayerCountdownV51(nextTime,tomorrow,timeZone)}
function startPrayerCountdownV51(time,tomorrow,timeZone){clearInterval(prayerCountdownTimer);const tick=()=>{const el=$('#ptCountdown');if(!el)return;const zoneMins=minutesInZone(timeZone);if(zoneMins==null){startPrayerCountdown(time,tomorrow);return}const [h,m]=time.split(':').map(Number);let sec=((h*60+m-zoneMins)+(tomorrow?1440:0))*60-new Date().getSeconds();if(sec<0)sec+=86400;const hh=String(Math.floor(sec/3600)).padStart(2,'0'),mm=String(Math.floor(sec%3600/60)).padStart(2,'0'),ss=String(sec%60).padStart(2,'0');el.textContent=hh+':'+mm+':'+ss};tick();prayerCountdownTimer=setInterval(tick,1000)}
