loadPrayerCoords=async function(lat,lon,label){const method=$('#ptMethod').value;$('#ptLocationTitle').textContent='جاري تحميل المواقيت…';try{const r=await fetch('https://api.aladhan.com/v1/timings/'+Math.floor(Date.now()/1000)+'?latitude='+encodeURIComponent(lat)+'&longitude='+encodeURIComponent(lon)+'&method='+encodeURIComponent(method)),j=await r.json();if(!r.ok||!j.data)throw 0;renderPrayerDashboardV51(j.data.timings,label||'موقعك الحالي',j.data.date,j.data.meta?.timezone)}catch(e){showCachedPrayers('تعذر الاتصال؛ هذه آخر مواقيت محفوظة.')}};
