const _geocodeQiblaCityV51=geocodeQiblaCity;geocodeQiblaCity=async function(){const city=$('#qiblaCity').value.trim(),country=$('#qiblaCountry').value.trim();if(!city||!country){$('#qiblaStatus').textContent='اختر الدولة والمدينة.';return}$('#qiblaStatus').textContent='جاري تحديد المدينة…';try{const r=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q='+encodeURIComponent(city+', '+country),{headers:{'Accept-Language':'ar,en'}}),j=await r.json();if(!r.ok||!j.length)throw 0;useSharedLocationAcrossPages(+j[0].lat,+j[0].lon,city+'، '+country)}catch(e){$('#qiblaStatus').textContent='تعذر العثور على المدينة الآن.'}};if($('#qiblaCityBtn'))$('#qiblaCityBtn').onclick=geocodeQiblaCity;
